initialize.fn:
function(instance, context) {
    instance.data.ready = false;
    instance.data.status = $('<div></div>').css({
        display: 'none', font: '12px/1.4 system-ui, sans-serif', color: '#475569',
        padding: '2px 8px', borderRadius: '999px', background: '#f1f5f9',
        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis'
    });
    instance.canvas.append(instance.data.status);
    if (!window.HibiraBubble) {
        instance.publishState('error', 'The Hibira runtime did not load.');
        return;
    }
    instance.data.hibira = new window.HibiraBubble.Element({
        publish: function (name, value) {
            instance.publishState(name, value);
            if (name === 'connection_state' && instance.data.status) {
                instance.data.status.text('Hibira: ' + value);
            }
        },
        trigger: function (name) { instance.triggerEvent(name); }
    });
    instance.data.ready = true;
}

update.fn:
function(instance, properties, context) {
    if (!instance.data.ready) return;
    instance.data.status.css('display', properties.show_status ? 'inline-block' : 'none');
    instance.data.hibira.update({
        app_key: context.keys['App key'],
        host: context.keys['Host'],
        channel: properties.channel,
        events: properties.events,
        value_key: properties.value_key,
        name_key: properties.name_key
    });
}

preview.fn:
function(instance, properties) {
    var label = properties.channel ? 'Hibira: ' + properties.channel : 'Hibira Channel';
    instance.canvas.append($('<div></div>').text(label).css({
        font: '12px/1.4 system-ui, sans-serif', color: '#0f172a', background: '#e0f2fe',
        border: '1px dashed #38bdf8', borderRadius: '6px', padding: '4px 8px',
        height: '100%', boxSizing: 'border-box', overflow: 'hidden', whiteSpace: 'nowrap'
    }));
}

server.fn:
async function(properties, context) {
  // ---- Hibira helpers ----
  // Bubble actions can't share modules, so every action's server.js starts with
  // this block. Edit tools/helpers.js, then run: node tools/sync-helpers.mjs
  const crypto = require('crypto');
  const keys = context.keys || {};
  const cfg = {
    appId: String(keys['App ID'] || '').trim(),
    key: String(keys['App key'] || '').trim(),
    secret: String(keys['App secret'] || '').trim(),
    base: apiBase(keys['Host'])
  };

  function apiBase(raw) {
    let host = String(raw || '').trim() || 'ws.hibira.io';
    let scheme = 'https';
    const m = host.match(/^(wss?|https?):\/\//i);
    if (m) {
      scheme = /^(wss|https)$/i.test(m[1]) ? 'https' : 'http';
      host = host.slice(m[0].length);
    }
    return scheme + '://' + host.replace(/\/.*$/, '');
  }

  function missingKeys(needSecretOnly) {
    const missing = [];
    if (!needSecretOnly && !cfg.appId) missing.push('App ID');
    if (!cfg.key) missing.push('App key');
    if (!cfg.secret) missing.push('App secret');
    if (!missing.length) return '';
    return 'Fill in ' + missing.join(', ') + ' in Plugins > Hibira Realtime. They are on your app page in the Hibira portal (https://hibira.io).';
  }

  function splitList(value) {
    const list = Array.isArray(value) ? value : String(value || '').split(/[,\n]/);
    return list.map((s) => String(s).trim()).filter((s) => s !== '');
  }

  function hmac(data) {
    return crypto.createHmac('sha256', cfg.secret).update(data).digest('hex');
  }

  // Signs a request like the Pusher HTTP API: auth_* query parameters and an
  // HMAC-SHA256 of "METHOD\nPATH\nsorted query", with body_md5 for a body.
  function signedUrl(method, path, query, body, now) {
    const q = Object.assign({}, query || {});
    q.auth_key = cfg.key;
    q.auth_timestamp = String(Math.floor((now || Date.now()) / 1000));
    q.auth_version = '1.0';
    if (body) q.body_md5 = crypto.createHash('md5').update(body).digest('hex');
    const canonical = Object.keys(q)
      .map((k) => [k.toLowerCase(), String(q[k])])
      .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .map((pair) => pair[0] + '=' + pair[1])
      .join('&');
    const signature = hmac(method + '\n' + path + '\n' + canonical);
    return cfg.base + path + '?' + canonical + '&auth_signature=' + signature;
  }

  async function hibira(method, resource, payload, query) {
    const path = '/apps/' + encodeURIComponent(cfg.appId) + resource;
    const body = payload === undefined ? '' : JSON.stringify(payload);
    const res = await fetch(signedUrl(method, path, query, body), {
      method: method,
      headers: body ? { 'Content-Type': 'application/json' } : {},
      body: body || undefined
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : {}; } catch (e) { json = null; }
    if (!res.ok) {
      const message = (json && (json.error || json.message)) || text || res.statusText;
      throw new Error('Hibira answered ' + res.status + ': ' + String(message).trim());
    }
    return json || {};
  }
  // ---- end Hibira helpers ----

  const problem = missingKeys(false);
  if (problem) return { ok: false, error: problem };
  const channels = splitList(properties.channels);
  const event = String(properties.event || '').trim();
  if (!channels.length) return { ok: false, error: 'Enter at least one channel.' };
  if (channels.length > 100) return { ok: false, error: 'At most 100 channels per event.' };
  if (!event) return { ok: false, error: 'Enter an event name.' };

  let data;
  const pairs = properties.data_fields || [];
  if (pairs.length) {
    const obj = {};
    pairs.forEach((pair) => { if (pair && pair.key) obj[pair.key] = pair.value; });
    data = JSON.stringify(obj);
  } else {
    const raw = properties.data === undefined || properties.data === null ? '' : String(properties.data);
    try { JSON.parse(raw); data = raw; } catch (e) { data = JSON.stringify({ text: raw }); }
    if (raw.trim() === '') data = '{}';
  }

  const body = { name: event, channels: channels, data: data };
  const socketId = String(properties.socket_id || '').trim();
  if (socketId) body.socket_id = socketId;
  try {
    await hibira('POST', '/events', body);
    return { ok: true, error: '' };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

